fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Assumes equal length as stated in the problem.
    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a ^ b)
        .collect()
}

